 public static List<(string Title,string Body)> Sections(string text){var result=new List<(string,string)>();string title="Результат";var body=new StringBuilder();foreach(var line in text.Replace("\r\n","\n").Split('\n')){if(line.StartsWith("## ")){if(body.ToString().Trim().Length>0)result.Add((title,body.ToString().Replace("\r\n","\n").TrimEnd()));title=line[3..];body.Clear();}else body.AppendLine(line);}if(body.ToString().Trim().Length>0)result.Add((title,body.ToString().Replace("\r\n","\n").TrimEnd()));return CleanSections40(result);}
 public static List<(string Title,string Body)> CleanSections40(List<(string Title,string Body)> source){
  var result=new List<(string Title,string Body)>();var seen=new HashSet<string>(StringComparer.Ordinal);
  foreach(var part in source){
   bool diagnostic=part.Title.Contains("диагност",StringComparison.OrdinalIgnoreCase);
   if(diagnostic){var meaningful=part.Body.Split('\n').Where(line=>!Regex.IsMatch(line,@"^\s*(?:--- .+ ---|(?:Диагностика: )?(?:запрошена|выполняется|собрана отдельно от основного задания|ожидает сбора|собрана|не запрошена|собирается · лимит 5 минут(?: · \d+ сек)?)\.?|(?:Запрос|Чтение|Сбор) (?:файлов )?диагностики(?:\.{3})?)\s*$",RegexOptions.IgnoreCase)).Select(x=>x.Trim()).Where(x=>x.Length>0).ToList();if(meaningful.Count==0)continue;}
